// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // Fuzz parameters: depositor (caller) and two deposit amounts. We allow the fuzzer
    // to pick address and amounts; keep domain wide. We use two deposits so userBalance[address(0)]
    // can differ from the caller's balance and reveal the mutant.
    function testFuzz_property(address depositor, uint128 a, uint128 b) public {
        // avoid zero address as depositor because EVM treats address(0) specially and mutant reads that slot
        vm.assume(depositor != address(0));

        // keep amounts non-zero but wide
        uint256 v1 = uint256(a) + 1;
        uint256 v2 = uint256(b) + 1;

        // Fund depositor so they can call payable addToBalance()
        vm.deal(depositor, v1 + v2 + 1 ether);

        // depositor makes first deposit v1
        vm.prank(depositor);
        c.addToBalance{value: v1}();

        // deposit into the zero address slot by impersonating address(0) via vm.prank
        // NOTE: solidity/test vm allows prank to any address; this simulates someone having balance at address(0)
        vm.deal(address(0), v2);
        vm.prank(address(0));
        c.addToBalance{value: v2}();

        // Record pre-withdraw values
        uint256 preCallerBalance = c.getBalance(depositor);
        uint256 preContractBal = address(c).balance;

        // Caller invokes withdrawBalance()
        vm.prank(depositor);
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a correct contract: caller's recorded userBalance must be zero AND contract balance must have decreased by exactly preCallerBalance (since it sent that amount out).
        // We assert that relationship (ties caller's stored balance to contract's balance change). The correct contract satisfies this for all inputs; the mutant breaks it for some inputs where it reads from address(0).

        uint256 postCallerBalance = c.getBalance(depositor);
        uint256 postContractBal = address(c).balance;

        // Compute contract balance decrease (may be zero if revert occurred)
        uint256 contractDecrease = preContractBal >= postContractBal ? preContractBal - postContractBal : 0;

        // The universal property: if withdraw did not revert, then caller's stored balance must be zero and the contract's balance must have decreased exactly by the caller's pre-withdraw recorded balance.
        if (ok) {
            assertTrue(postCallerBalance == 0 && contractDecrease == preCallerBalance);
        } else {
            // If withdraw reverted, then nothing should have been changed: both caller balance and contract balance unchanged
            assertTrue(postCallerBalance == preCallerBalance && postContractBal == preContractBal);
        }
    }
}
